package com.github.oleksandrkukotin.jowl.crawler.javadoc;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Disabled;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

import static org.assertj.core.api.Assertions.assertThat;

class JavadocPageParserTest {

    // Fixture generated by the JDK 21 javadoc tool from a small sample class
    private static final String FIXTURE = "/javadoc/Greeter.html";
    private static final String PAGE_URL = "https://docs.example.com/api/com/example/Greeter.html";

    private final JavadocPageParser parser = new JavadocPageParser();
    private JavadocCrawledPage page;

    @BeforeEach
    void parseFixture() throws IOException {
        page = parser.parsePage(PAGE_URL, loadFixture()).orElseThrow();
    }

    @Test
    void returnsEmptyForNullDocument() {
        assertThat(parser.parsePage(PAGE_URL, null)).isEmpty();
    }

    @Test
    void keepsPageUrl() {
        assertThat(page.url()).isEqualTo(PAGE_URL);
    }

    @Test
    void extractsClassNameFromHeading() {
        assertThat(page.className()).contains("Greeter");
    }

    @Test
    void extractsClassDescription() {
        assertThat(page.classDescription()).contains("Builds friendly greetings.");
    }

    @Test
    void resolvesRelativeLinksAgainstPageUrl() {
        assertThat(page.links()).contains(
                "https://docs.example.com/api/com/example/package-summary.html",
                "https://docs.example.com/api/index-all.html");
    }

    @Test
    void dropsLinksToOtherDomains() {
        assertThat(page.links()).noneMatch(link -> link.contains("docs.oracle.com"));
    }

    @Test
    void dropsLinksWithFragments() {
        assertThat(page.links()).noneMatch(link -> link.contains("#"));
    }

    @Test
    @Disabled("Bug: section#method-detail wraps all methods, so they are parsed as one merged method")
    void extractsEachMethodSeparately() {
        assertThat(page.methods())
                .extracting(JavadocMethod::name)
                .containsExactlyInAnyOrder("greet", "count");
    }

    @Test
    @Disabled("Bug: div.block also matches method and constructor descriptions")
    void classDescriptionExcludesMemberDescriptions() {
        assertThat(page.classDescription()).doesNotContain("Returns a greeting for the given name.");
    }

    private static Document loadFixture() throws IOException {
        try (InputStream html = JavadocPageParserTest.class.getResourceAsStream(FIXTURE)) {
            return Jsoup.parse(html, StandardCharsets.UTF_8.name(), PAGE_URL);
        }
    }
}
